function toFullwidth(s){
  var o=''; var t=String(s||'');
  for(var i=0;i<t.length;i++){ var c=t.charCodeAt(i);
    if(c===0x20){ o+=String.fromCharCode(0x3000); }
    else if(c>=0x21 && c<=0x7E){ o+=String.fromCharCode(c+0xFEE0); }
    else o+=t.charAt(i);
  } return o;
}
function toHalfwidth(s){
  var o=''; var t=String(s||'');
  for(var i=0;i<t.length;i++){ var c=t.charCodeAt(i);
    if(c===0x3000){ o+=' '; }
    else if(c>=0xFF01 && c<=0xFF5E){ o+=String.fromCharCode(c-0xFEE0); }
    else o+=t.charAt(i);
  } return o;
}

var EXPORTS={toFullwidth:toFullwidth,toHalfwidth:toHalfwidth};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.FullwidthForgePure = EXPORTS; }
